import os
import time
from pathlib import Path


class AutoReloadManager:
    """Manages automatic reloading with tracking for manage.py changes."""

    def __init__(self, project_root=None, poll_interval=1.0):
        self.project_root = Path(project_root) if project_root else Path.cwd()
        self._manage_py_mtime = 0.0
        self.manage_py_changed = False
        self._on_manage_py_change_callbacks = []
        self._server_restart_callback = None
        self._poll_interval = poll_interval
        self._monitoring = False

    @property
    def manage_py_path(self):
        return self.project_root / "manage.py"

    def register_callback(self, callback):
        """Register a callback to be invoked when manage.py changes."""
        if callback not in self._on_manage_py_change_callbacks:
            self._on_manage_py_change_callbacks.append(callback)

    def set_server_restart_callback(self, callback):
        """Set the callback to trigger server restart on change detection."""
        self._server_restart_callback = callback

    def _get_manage_py_mtime(self):
        try:
            return os.path.getmtime(self.manage_py_path)
        except OSError:
            return 0.0

    def check_manage_py_changes(self):
        """Check for changes to manage.py and trigger callbacks."""
        current_mtime = self._get_manage_py_mtime()
        if current_mtime > self._manage_py_mtime:
            self.manage_py_changed = True
            self._manage_py_mtime = current_mtime
            for cb in self._on_manage_py_change_callbacks:
                cb()
            if self._server_restart_callback and self.manage_py_changed:
                self._server_restart_callback()
            return True
        return False

    def start_monitoring(self):
        """Start periodic polling to detect manage.py changes."""
        self._monitoring = True
        while self._monitoring:
            if self.check_manage_py_changes():
                pass  # Callbacks already triggered in check_manage_py_changes()
            time.sleep(self._poll_interval)

    def stop_monitoring(self):
        """Stop the periodic polling loop."""
        self._monitoring = False

    def reset(self):
        self.manage_py_changed = False
        self._manage_py_mtime = 0.0
        self._on_manage_py_change_callbacks.clear()

    def __repr__(self):
        return (f"AutoReloadManager(project_root={self.project_root}, "
                f"manage_py_changed={self.manage_py_changed})")

